  ('d13a', 'dm-1-3', '3', '', null, null, seed_tmp.ts(-331256), null, null),
  ('an1', 'announcements', '1', 'Welcome to LevelUp chats! Announcements, Main chat, Daily wins and High signal are pinned at the top of Groups, and direct messages have their own tab. Pin any chat you use a lot.', null, null, seed_tmp.ts(-288056), null, null),
  ('d17a', 'dm-1-7', '1', 'Did you grab your ticket yet?', null, null, seed_tmp.ts(-277256), null, null),
