  ('cp4', 'carpool', '3', 'I can take 3 from Plano', null, null, seed_tmp.ts(-78956), null, null),
  ('mc1', 'main', '1', 'Great meeting last night, everyone. This month the focus is Fall Weekend tickets.', null, null, seed_tmp.ts(-75656), null, null),
